def is_monotonic_sequence(lst, increasing=True):
    """
    Checks if a list is strictly increasing or strictly decreasing.

    Args:
        lst: List of comparable elements
        increasing: If True, checks for strictly increasing; 
                    if False, checks for strictly decreasing

    Returns:
        bool: True if the list is strictly monotonic in the specified direction
    """
    if len(lst) < 2:
        return True

    if increasing:
        return all(lst[i] < lst[i + 1] for i in range(len(lst) - 1))
    else:
        return all(lst[i] > lst[i + 1] for i in range(len(lst) - 1))


