def select_words(s, n):
    # Define the set of vowels for constant-time lookups
    vowels = set("aeiouAEIOU")

    # Functional helper to count consonants in a single word
    def count_consonants(word):
        # Filter characters that are letters and not vowels, then count
        return len(list(filter(lambda char: char.isalpha() and char not in vowels, word)))

    # Check if the string is empty (base case)
    if not s:
        return []

    # 1. Split the string into a list of words
    # 2. Map each word to its consonant count
    # 3. Filter the original words where the count equals n
    # 4. Convert the resulting iterator back to a list
    return list(
        map(
            lambda pair: pair[0],
            filter(
                lambda pair: pair[1] == n,
                zip(s.split(), map(count_consonants, s.split()))
            )
        )
    )

